css:
:root {
  /* Notecard Desk Theme - lined index cards on a walnut desk */
  --bg-primary: #fdfbf7;
  --bg-alt: #f6f1e8;
  --bg-hover: #ede3d5;
  --text-primary: #2d2b26;
  --text-secondary: #6b6354;
  --border: #c2b7a3;
  --accent: #2f6fb1;
  --accent-hover: #235385;
  --ink: #2b2b2b;
  --paper-line: #d9d3c7;
  --paper-rule: #2f6fb1;
}

[data-theme="dark"] {
  --bg-primary: #1c1710;
  --bg-alt: #221c13;
  --bg-hover: #2b2318;
  --text-primary: #f6f1e8;
  --text-secondary: #cbbfa7;
  --border: #6b6354;
  --accent: #72a9e6;
  --accent-hover: #99c4f0;
  --ink: #fdfbf7;
  --paper-line: #3a3125;
  --paper-rule: #72a9e6;
}

body {
  background: linear-gradient(120deg, #5a3c24 0%, #3f2a1a 100%);
}

.card {
  background: repeating-linear-gradient(0deg, transparent 0px, transparent 26px, rgba(47, 111, 177, 0.12) 26px, rgba(47, 111, 177, 0.12) 27px),
              repeating-linear-gradient(90deg, rgba(201, 183, 163, 0.6) 0, rgba(201, 183, 163, 0.6) 1px, transparent 1px, transparent 16px),
              var(--bg-primary);
  border: 2px solid var(--paper-line);
  box-shadow: 0 16px 32px rgba(0, 0, 0, 0.2);
  color: var(--ink);
}

.card-title {
  font-family: 'Courier New', monospace;
  letter-spacing: 0.4px;
  color: var(--accent);
}

.tag {
  background: rgba(47, 111, 177, 0.1);
  border: 1px solid var(--accent);
  color: var(--ink);
}
